}

function parseManifest(manifest) {
  const invalid = () => fail('ERR_INVALID_MANIFEST', 'Invalid restore manifest');
  const top = exactFields(manifest, ['writes', 'deletes']);
  if (!top) throw invalid();
  const rawWrites = snapshotArray(top.writes);
  const deletes = snapshotArray(top.deletes);
  if (!rawWrites || !deletes) throw invalid();

  const writes = rawWrites.map(item => {
    const write = exactFields(item, ['path', 'content']);
    if (!write || typeof write.path !== 'string' || typeof write.content !== 'string') throw invalid();
    return write;
  });
  if (!deletes.every(item => typeof item === 'string')) throw invalid();

  const targets = [...writes.map(write => write.path), ...deletes];
  for (const target of targets) {
    if (!isPortablePath(target)) throw fail('ERR_INVALID_PATH', 'Invalid manifest path');
  }

  const seen = new Set();
  for (const target of targets) {
    if (seen.has(target)) throw invalid();
    seen.add(target);
  }
  for (const target of targets) {
    const segments = target.split('/');
    for (let length = 1; length < segments.length; length += 1) {
      if (seen.has(segments.slice(0, length).join('/'))) throw invalid();
    }
  }
  return { writes, deletes };
