export async function restore(directory, manifest, grants) {
  const { writes, deletes } = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const write of writes) {
    if (!approved.has(`write:${write.path}`)) throw fail('ERR_DENIED', 'Write not approved');
  }
  for (const target of deletes) {
    if (!approved.has(`delete:${target}`)) throw fail('ERR_DENIED', 'Delete not approved');
  }

