import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function expect(name, promise, code) {
  try { const r = await promise; results.push(`${code ? 'FAIL' : 'ok  '} ${name} -> ${JSON.stringify(r)}`); }
  catch (e) { results.push(`${e.code === code ? 'ok  ' : 'FAIL'} ${name} -> ${e.code}`); }
}
const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-'));
const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-out-'));
await fs.writeFile(path.join(dir, '.hidden'), 'h');
await fs.mkdir(path.join(dir, 'sub'));
await fs.writeFile(path.join(dir, 'sub/keep.txt'), 'k');
await fs.writeFile(path.join(dir, 'old.txt'), 'o');
await fs.writeFile(path.join(outside, 'secret.txt'), 's');
await fs.symlink(outside, path.join(dir, 'link'), 'junction');
await fs.mkdir(path.join(dir, 'adir'));
const W = (p, c = 'x') => ({ writes: [{ path: p, content: c }], deletes: [] });
const g = (path, operation) => ({ path, operation });

await expect('approved field', restore(dir, { ...W('a.txt'), approved: true }, []), 'ERR_INVALID_MANIFEST');
await expect('prefix grant', restore(dir, W('sub/x.txt'), [g('sub', 'write')]), 'ERR_DENIED');
await expect('string prefix grant', restore(dir, W('ab.txt'), [g('a', 'write')]), 'ERR_DENIED');
await expect('wrong op', restore(dir, W('a.txt'), [g('a.txt', 'delete')]), 'ERR_DENIED');
await expect('dotdot', restore(dir, W('../a.txt'), [g('a.txt', 'write')]), 'ERR_INVALID_PATH');
await expect('device', restore(dir, W('dir/con.txt'), []), 'ERR_INVALID_PATH');
await expect('backslash', restore(dir, W('a\\b'), []), 'ERR_INVALID_PATH');
await expect('upper', restore(dir, W('A.txt'), []), 'ERR_INVALID_PATH');
await expect('absolute', restore(dir, W('/a'), []), 'ERR_INVALID_PATH');
await expect('dup', restore(dir, { writes: [{ path: 'a', content: '' }], deletes: ['a'] }, []), 'ERR_INVALID_MANIFEST');
await expect('ancestor', restore(dir, { writes: [{ path: 'a', content: '' }, { path: 'a/b', content: '' }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('bad content', restore(dir, W('a.txt', 3), []), 'ERR_INVALID_MANIFEST');
await expect('bad grant', restore(dir, W('a.txt'), [g('../a.txt', 'write')]), 'ERR_INVALID_GRANT');
await expect('grant extra', restore(dir, W('a.txt'), [{ ...g('a.txt', 'write'), all: true }]), 'ERR_INVALID_GRANT');
await expect('junction parent', restore(dir, W('link/secret.txt', 'pwn'), [g('link/secret.txt', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('junction delete', restore(dir, { writes: [], deletes: ['link'] }, [g('link', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('dir target', restore(dir, { writes: [], deletes: ['adir'] }, [g('adir', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('file as parent', restore(dir, W('old.txt/x'), [g('old.txt/x', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('late unsafe no mutation', restore(dir, { writes: [{ path: 'new/a.txt', content: 'n' }, { path: 'link/z', content: 'z' }], deletes: [] }, [g('new/a.txt', 'write'), g('link/z', 'write')]), 'ERR_UNSAFE_TARGET');
