results.push(`${newExists ? 'FAIL' : 'ok  '} no parent created on rejection`);
await expect('happy', restore(dir, { writes: [{ path: 'sub/keep.txt', content: 'K2' }, { path: 'deep/n/x.txt', content: 'd' }], deletes: ['old.txt', 'missing.txt', 'nope/x'] },
  [g('sub/keep.txt', 'write'), g('deep/n/x.txt', 'write'), g('old.txt', 'delete'), g('missing.txt', 'delete'), g('nope/x', 'delete'), g('old.txt', 'delete')]));
results.push(`state: hidden=${await fs.readFile(path.join(dir, '.hidden'), 'utf8')} keep=${await fs.readFile(path.join(dir, 'sub/keep.txt'), 'utf8')} secret=${await fs.readFile(path.join(outside, 'secret.txt'), 'utf8')} adir=${(await fs.stat(path.join(dir, 'adir'))).isDirectory()} entries=${(await fs.readdir(dir)).sort()}`);
const rootLink = path.join(outside, 'rootlink');
await fs.symlink(dir, rootLink, 'junction');
await expect('symlink root', restore(rootLink, W('a.txt'), [g('a.txt', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('empty', restore(dir, { writes: [], deletes: [] }, []));
console.log(results.join('\n'));
await fs.unlink(rootLink);
await fs.unlink(path.join(dir, 'link'));
await fs.rm(dir, { recursive: true });
await fs.rm(outside, { recursive: true });

