import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isRecord(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// Snapshot exactly the expected own data properties; any other own key
// (string or symbol), missing key, or accessor makes the shape invalid.
function exactFields(value, fields) {
  if (!isRecord(value)) return null;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== fields.length) return null;
  const copy = {};
  for (const field of fields) {
    const descriptor = Object.getOwnPropertyDescriptor(value, field);
    if (!descriptor || !('value' in descriptor)) return null;
    copy[field] = descriptor.value;
  }
  return copy;
}

function snapshotArray(value) {
  if (!Array.isArray(value)) return null;
  const items = [];
  for (let index = 0; index < value.length; index += 1) {
    if (!Object.prototype.hasOwnProperty.call(value, index)) return null;
    items.push(value[index]);
  }
  return items;
}

function isPortablePath(value) {
  if (typeof value !== 'string' || value.length === 0) return false;
  return value.split('/').every(segment =>
    SEGMENT.test(segment) && !DEVICE_STEM.test(segment.split('.')[0]));
}

function parseManifest(manifest) {
  const invalid = () => fail('ERR_INVALID_MANIFEST', 'Invalid restore manifest');
  const top = exactFields(manifest, ['writes', 'deletes']);
  if (!top) throw invalid();
  const rawWrites = snapshotArray(top.writes);
  const deletes = snapshotArray(top.deletes);
  if (!rawWrites || !deletes) throw invalid();

  const writes = rawWrites.map(item => {
    const write = exactFields(item, ['path', 'content']);
    if (!write || typeof write.path !== 'string' || typeof write.content !== 'string') throw invalid();
    return write;
  });
  if (!deletes.every(item => typeof item === 'string')) throw invalid();

  const targets = [...writes.map(write => write.path), ...deletes];
  for (const target of targets) {
    if (!isPortablePath(target)) throw fail('ERR_INVALID_PATH', 'Invalid manifest path');
  }

  const seen = new Set();
  for (const target of targets) {
    if (seen.has(target)) throw invalid();
    seen.add(target);
  }
  for (const target of targets) {
    const segments = target.split('/');
    for (let length = 1; length < segments.length; length += 1) {
      if (seen.has(segments.slice(0, length).join('/'))) throw invalid();
    }
  }
  return { writes, deletes };
}

function parseGrants(grants) {
  const invalid = () => fail('ERR_INVALID_GRANT', 'Invalid grant');
  const items = snapshotArray(grants);
  if (!items) throw invalid();
  const approved = new Set();
  for (const item of items) {
    const grant = exactFields(item, ['path', 'operation']);
    if (!grant || !OPERATIONS.has(grant.operation) || !isPortablePath(grant.path)) throw invalid();
    approved.add(`${grant.operation}:${grant.path}`);
  }
  return approved;
}

async function lstatOrNull(target) {
  try {
    return await fs.lstat(target);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

async function checkTarget(root, relative) {
  const unsafe = () => fail('ERR_UNSAFE_TARGET', 'Unsafe restore target');
  const segments = relative.split('/');
  let current = root;
  for (let index = 0; index < segments.length; index += 1) {
    current = path.join(current, segments[index]);
    const stats = await lstatOrNull(current);
    if (stats === null) return; // Absent component: nothing below it exists.
    if (stats.isSymbolicLink()) throw unsafe();
    const last = index === segments.length - 1;
    if (last ? !stats.isFile() : !stats.isDirectory()) throw unsafe();
  }
}

export async function restore(directory, manifest, grants) {
  const { writes, deletes } = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const write of writes) {
    if (!approved.has(`write:${write.path}`)) throw fail('ERR_DENIED', 'Write not approved');
  }
  for (const target of deletes) {
    if (!approved.has(`delete:${target}`)) throw fail('ERR_DENIED', 'Delete not approved');
  }

  const root = path.resolve(directory);
  const rootStats = await fs.lstat(root);
  if (rootStats.isSymbolicLink() || !rootStats.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Unsafe restore root');
  }
  for (const target of [...writes.map(write => write.path), ...deletes]) {
    await checkTarget(root, target);
  }

  const written = [];
  const deleted = [];
  for (const write of writes) {
    const target = path.join(root, ...write.path.split('/'));
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, write.content, 'utf8');
    written.push(write.path);
  }
  for (const relative of deletes) {
    try {
      await fs.unlink(path.join(root, ...relative.split('/')));
      deleted.push(relative);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
  }
  return { written, deleted };
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function expect(name, promise, code) {
  try { const r = await promise; results.push(`${code ? 'FAIL' : 'ok  '} ${name} -> ${JSON.stringify(r)}`); }
  catch (e) { results.push(`${e.code === code ? 'ok  ' : 'FAIL'} ${name} -> ${e.code}`); }
}
const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-'));
const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-out-'));
await fs.writeFile(path.join(dir, '.hidden'), 'h');
await fs.mkdir(path.join(dir, 'sub'));
await fs.writeFile(path.join(dir, 'sub/keep.txt'), 'k');
await fs.writeFile(path.join(dir, 'old.txt'), 'o');
await fs.writeFile(path.join(outside, 'secret.txt'), 's');
await fs.symlink(outside, path.join(dir, 'link'), 'junction');
await fs.mkdir(path.join(dir, 'adir'));
const W = (p, c = 'x') => ({ writes: [{ path: p, content: c }], deletes: [] });
const g = (path, operation) => ({ path, operation });

await expect('approved field', restore(dir, { ...W('a.txt'), approved: true }, []), 'ERR_INVALID_MANIFEST');
await expect('prefix grant', restore(dir, W('sub/x.txt'), [g('sub', 'write')]), 'ERR_DENIED');
await expect('string prefix grant', restore(dir, W('ab.txt'), [g('a', 'write')]), 'ERR_DENIED');
await expect('wrong op', restore(dir, W('a.txt'), [g('a.txt', 'delete')]), 'ERR_DENIED');
await expect('dotdot', restore(dir, W('../a.txt'), [g('a.txt', 'write')]), 'ERR_INVALID_PATH');
await expect('device', restore(dir, W('dir/con.txt'), []), 'ERR_INVALID_PATH');
await expect('backslash', restore(dir, W('a\\b'), []), 'ERR_INVALID_PATH');
await expect('upper', restore(dir, W('A.txt'), []), 'ERR_INVALID_PATH');
await expect('absolute', restore(dir, W('/a'), []), 'ERR_INVALID_PATH');
await expect('dup', restore(dir, { writes: [{ path: 'a', content: '' }], deletes: ['a'] }, []), 'ERR_INVALID_MANIFEST');
await expect('ancestor', restore(dir, { writes: [{ path: 'a', content: '' }, { path: 'a/b', content: '' }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('bad content', restore(dir, W('a.txt', 3), []), 'ERR_INVALID_MANIFEST');
await expect('bad grant', restore(dir, W('a.txt'), [g('../a.txt', 'write')]), 'ERR_INVALID_GRANT');
await expect('grant extra', restore(dir, W('a.txt'), [{ ...g('a.txt', 'write'), all: true }]), 'ERR_INVALID_GRANT');
await expect('junction parent', restore(dir, W('link/secret.txt', 'pwn'), [g('link/secret.txt', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('junction delete', restore(dir, { writes: [], deletes: ['link'] }, [g('link', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('dir target', restore(dir, { writes: [], deletes: ['adir'] }, [g('adir', 'delete')]), 'ERR_UNSAFE_TARGET');
await expect('file as parent', restore(dir, W('old.txt/x'), [g('old.txt/x', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('late unsafe no mutation', restore(dir, { writes: [{ path: 'new/a.txt', content: 'n' }, { path: 'link/z', content: 'z' }], deletes: [] }, [g('new/a.txt', 'write'), g('link/z', 'write')]), 'ERR_UNSAFE_TARGET');
const newExists = await fs.lstat(path.join(dir, 'new')).then(() => true, () => false);
results.push(`${newExists ? 'FAIL' : 'ok  '} no parent created on rejection`);
await expect('happy', restore(dir, { writes: [{ path: 'sub/keep.txt', content: 'K2' }, { path: 'deep/n/x.txt', content: 'd' }], deletes: ['old.txt', 'missing.txt', 'nope/x'] },
  [g('sub/keep.txt', 'write'), g('deep/n/x.txt', 'write'), g('old.txt', 'delete'), g('missing.txt', 'delete'), g('nope/x', 'delete'), g('old.txt', 'delete')]));
results.push(`state: hidden=${await fs.readFile(path.join(dir, '.hidden'), 'utf8')} keep=${await fs.readFile(path.join(dir, 'sub/keep.txt'), 'utf8')} secret=${await fs.readFile(path.join(outside, 'secret.txt'), 'utf8')} adir=${(await fs.stat(path.join(dir, 'adir'))).isDirectory()} entries=${(await fs.readdir(dir)).sort()}`);
const rootLink = path.join(outside, 'rootlink');
await fs.symlink(dir, rootLink, 'junction');
await expect('symlink root', restore(rootLink, W('a.txt'), [g('a.txt', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('empty', restore(dir, { writes: [], deletes: [] }, []));
console.log(results.join('\n'));
await fs.unlink(rootLink);
await fs.unlink(path.join(dir, 'link'));
await fs.rm(dir, { recursive: true });
await fs.rm(outside, { recursive: true });

